import os
import json
from typing import Any, Dict, List, Optional

import boto3


def _block_map(blocks: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    return {b["Id"]: b for b in blocks if "Id" in b}


def _child_ids(block: Dict[str, Any], rel_type: str = "CHILD") -> List[str]:
    ids: List[str] = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") == rel_type:
            ids.extend(rel.get("Ids", []))
    return ids


def _text_for_block(block: Dict[str, Any], blocks_by_id: Dict[str, Dict[str, Any]]) -> str:
    parts: List[str] = []
    for cid in _child_ids(block, "CHILD"):
        child = blocks_by_id.get(cid)
        if not child:
            continue
        btype = child.get("BlockType")
        if btype == "WORD":
            text = child.get("Text")
            if text:
                parts.append(text)
        elif btype == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
            parts.append("X")
    return " ".join(parts).strip()


def _entity_types(block: Dict[str, Any]) -> List[str]:
    return block.get("EntityTypes", []) or []


def extract_key_value_pairs_from_form(
    *,
    file_path: Optional[str] = None,
    s3_bucket: Optional[str] = None,
    s3_object_name: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    if not file_path and not (s3_bucket and s3_object_name):
        raise ValueError("Provide either file_path or both s3_bucket and s3_object_name.")

    client = boto3.client(
        "textract",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
    )

    if file_path:
        with open(file_path, "rb") as f:
            document = {"Bytes": f.read()}
    else:
        document = {"S3Object": {"Bucket": s3_bucket, "Name": s3_object_name}}

    response = client.analyze_document(
        Document=document,
        FeatureTypes=["FORMS"],
    )

    blocks = response.get("Blocks", [])
    blocks_by_id = _block_map(blocks)

    keys: Dict[str, Dict[str, Any]] = {}
    values: Dict[str, Dict[str, Any]] = {}

    for block in blocks:
        if block.get("BlockType") != "KEY_VALUE_SET":
            continue
        entities = _entity_types(block)
        if "KEY" in entities:
            keys[block["Id"]] = block
        elif "VALUE" in entities:
            values[block["Id"]] = block

    result_pairs: Dict[str, Any] = {}

    for key_id, key_block in keys.items():
        key_text = _text_for_block(key_block, blocks_by_id)
        if not key_text:
            continue

        value_texts: List[str] = []
        for value_id in _child_ids(key_block, "VALUE"):
            value_block = values.get(value_id) or blocks_by_id.get(value_id)
            if not value_block:
                continue
            text = _text_for_block(value_block, blocks_by_id)
            if text:
                value_texts.append(text)

        if key_text in result_pairs:
            existing = result_pairs[key_text]
            if isinstance(existing, list):
                existing.extend(v for v in value_texts if v not in existing)
            else:
                merged = [existing]
                merged.extend(v for v in value_texts if v != existing)
                result_pairs[key_text] = merged
        else:
            if not value_texts:
                result_pairs[key_text] = ""
            elif len(value_texts) == 1:
                result_pairs[key_text] = value_texts[0]
            else:
                result_pairs[key_text] = value_texts

    return {
        "provider": "aws-textract",
        "model_family": "Amazon Textract AnalyzeDocument FORMS",
        "key_value_pairs": result_pairs,
        "raw_block_count": len(blocks),
    }


def extract_key_value_pairs_json(**kwargs: Any) -> str:
    return json.dumps(extract_key_value_pairs_from_form(**kwargs), ensure_ascii=False, indent=2)
